const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let p = 0;

const N = data[p++], M = data[p++], K = data[p++];
const spellA = data.slice(p, p + N); p += N;
const spellB = data.slice(p, p + N); p += N;
const mealA = data.slice(p, p + M); p += M;
const mealB = data.slice(p, p + M); p += M;
const Q = data[p++];
const queries = data.slice(p, p + Q);

const MOD = 1000000007n;

// Build the upper envelope of spell effects.
let spells = [];
for (let i = 0; i < N; i++) {
  spells.push({ a: spellA[i], b: spellB[i] });
}
spells.sort((x, y) => x.a - y.a || y.b - x.b);

const uniqueSpells = [];
for (const s of spells) {
  if (!uniqueSpells.length || uniqueSpells[uniqueSpells.length - 1].a !== s.a) {
    uniqueSpells.push({ a: s.a, b: s.b, A: BigInt(s.a), B: BigInt(s.b), start: null });
  }
}

function ceilDiv(n, d) {
  if (n >= 0n) return (n + d - 1n) / d;
  return n / d;
}

const hull = [];
for (const line of uniqueSpells) {
  let start = null;
  while (hull.length) {
    const prev = hull[hull.length - 1];
    start = ceilDiv(BigInt(prev.b - line.b), BigInt(line.a - prev.a));
    if (hull.length === 1 || start > prev.start) break;
    hull.pop();
  }
  if (!hull.length) start = null;
  line.start = start;
  hull.push(line);
}

function findLine(y) {
  let lo = 1, hi = hull.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (hull[mid].start <= y) lo = mid + 1;
    else hi = mid;
  }
  return lo - 1;
}

function applyPower(value, line, count) {
  let n = BigInt(count);
  let resultA = 1n, resultB = 0n;
  let baseA = line.A, baseB = line.B;

  while (n > 0n) {
    if (n & 1n) {
      resultB = (baseA * resultB + baseB) % MOD;
      resultA = (baseA * resultA) % MOD;
    }
    baseB = (baseA * baseB + baseB) % MOD;
    baseA = (baseA * baseA) % MOD;
    n >>= 1n;
  }
  return (resultA * value + resultB) % MOD;
}

// Order meals by decreasing b/(a-1), treating a=1 as infinite.
const meals = [];
for (let i = 0; i < M; i++) {
  meals.push({ a: mealA[i], b: mealB[i] });
}
meals.sort((x, y) => {
  const dx = x.a - 1, dy = y.a - 1;
  if (dx === 0 || dy === 0) {
    if (dx === 0 && dy === 0) return 0;
    return dx === 0 ? -1 : 1;
  }
  const left = BigInt(x.b) * BigInt(dy);
  const right = BigInt(y.b) * BigInt(dx);
  return left === right ? 0 : (left > right ? -1 : 1);
});

let mealMul = 1n, mealAdd = 0n;
for (const meal of meals) {
  const a = BigInt(meal.a), b = BigInt(meal.b);
  mealMul = (a * mealMul) % MOD;
  mealAdd = (a * mealAdd + b) % MOD;
}

const output = [];
for (const x of queries) {
  let y = BigInt(x);
  let value = BigInt(x) % MOD;
  let remaining = K;

  while (remaining > 0) {
    const idx = findLine(y);
    const line = hull[idx];

    if (idx === hull.length - 1) {
      value = applyPower(value, line, remaining);
      remaining = 0;
      break;
    }

    const threshold = hull[idx + 1].start;

    if (line.a === 1) {
      const steps = (threshold - y + line.B - 1n) / line.B;
      const take = steps < BigInt(remaining) ? steps : BigInt(remaining);

      y += take * line.B;
      value = (value + (take % MOD) * line.B) % MOD;
      remaining -= Number(take);
    } else {
      while (remaining > 0 && y < threshold) {
        y = line.A * y + line.B;
        value = (line.A * value + line.B) % MOD;
        remaining--;
      }
    }
  }

  value = (mealMul * value + mealAdd) % MOD;
  output.push(value.toString());
}

console.log(output.join('\n'));
